select count(*) selected_rows,count(*)filter(where pii_purged_at is not null) marked,
count(*)filter(where customer_name is not null or customer_email is not null or customer_phone is not null or shipping_address<>'{}' or billing_address<>'{}' or raw_payload<>'{}') buyer_data_violations,
count(*)filter(where tracking_number is not null or tracking_url is not null or shipping_label_url is not null or shipping_remote_id is not null or sendcloud_parcel_id is not null or sendcloud_shipment_id is not null or sendcloud_remote_id is not null or sendcloud_id<>'amazon-purged:'||id::text or shopify_tracking_synced_number is not null) capability_violations,
count(*)filter(where items is distinct from baseline->'items' or total_amount is distinct from (baseline->>'total_amount')::numeric or currency is distinct from baseline->>'currency' or destination_country_code is distinct from baseline->>'country' or shipping_cost_amount is distinct from (baseline->>'shipping_cost_amount')::numeric or shipping_cost_net_amount is distinct from (baseline->>'shipping_cost_net_amount')::numeric or shipping_cost_tax_amount is distinct from (baseline->>'shipping_cost_tax_amount')::numeric) economic_violations,
count(*)filter(where order_created_at+interval '1440 hours'>pii_purged_at) deadline_violations,
min(order_created_at) oldest_purchase,max(order_created_at+interval '1440 hours') newest_deadline,
(select count(*) from fulfillment_orders where pii_purged_at is not null) all_marked,
(select count(*) from private.amazon_pii_tombstones) tombstones,
(select count(*) from private.amazon_pii_execution_gates where pilot_verified_at is not null) remaining_batch_gates_open
from s;
